def transform(grid):
    # Columns with >1 non-zero become 4, rows with >1 non-zero become 7
    # Here 6 and 3 are vertical (span across rows in a single column)
    # 5 and 1 are horizontal (span across columns in a single row)
    import numpy as np
    g = np.array(grid)
    out = np.zeros_like(g)
    for c in range(g.shape[1]):
        col = g[:, c]
        nonzeros = np.where(col != 0)[0]
        if len(nonzeros) > 1 and len(set(nonzeros)) == len(nonzeros): # vertical segment
            # check if part of horizontal or vertical
            pass
    # simple: if neighbor above/below has same color, 4; if neighbor left/right has same color, 7
    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            if g[r, c] != 0:
                is_v = (r > 0 and g[r-1, c] == g[r, c]) or (r+1 < g.shape[0] and g[r+1, c] == g[r, c])
                out[r, c] = 4 if is_v else 7
    return out.tolist()
